'use client';
import { useRef, useState } from 'react';

export function {{component_name}}() {
  const ref = useRef<HTMLAudioElement>(null);
  const [playing, setPlaying] = useState(false);
  const [t, setT] = useState(0); const [dur, setDur] = useState(0);
  return (
    <div>
      <audio ref={ref} src="{{src}}" onTimeUpdate={e => setT(e.currentTarget.currentTime)} onLoadedMetadata={e => setDur(e.currentTarget.duration)} />
      <button onClick={() => { const a = ref.current!; playing ? a.pause() : a.play(); setPlaying(!playing); }}>{playing ? '⏸' : '▶'}</button>
      <input type="range" min={0} max={dur} value={t} onChange={e => { ref.current!.currentTime = +e.target.value; }} />
      <span>{t.toFixed(1)} / {dur.toFixed(1)}</span>
    </div>
  );
}
